export type DiaryRecurrence = 'daily' | 'weekly' | 'monthly' | 'quarterly' | 'yearly'
export type DiaryTemplateInput = {
  title: string
  instructions?: string
  recurrence: DiaryRecurrence
  dueTime: string
  weekday?: string
  monthDay?: string
  annualMonth?: string
  timezone: string
  assigneeId?: string
}

export function diaryRecurrenceCron(
  input: Pick<DiaryTemplateInput, 'recurrence' | 'dueTime' | 'weekday' | 'monthDay' | 'annualMonth'>,
): string {
  if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(input.dueTime)) throw new Error('Due time must use HH:MM.')
  const [hour, minute] = input.dueTime.split(':').map(Number)
  if (input.recurrence === 'daily') return `${minute} ${hour} * * *`
  if (input.recurrence === 'weekly') {
    const weekday = Number(input.weekday)
    if (!Number.isInteger(weekday) || weekday < 0 || weekday > 6)
      throw new Error('Weekly recurrence requires a valid weekday.')
    return `${minute} ${hour} * * ${weekday}`
  }
  if (!['monthly', 'quarterly', 'yearly'].includes(input.recurrence))
    throw new Error('Invalid diary recurrence.')
  const monthDay = Number(input.monthDay)
  if (!Number.isInteger(monthDay) || monthDay < 1 || monthDay > 28)
    throw new Error('Monthly recurrence requires a day between 1 and 28.')
  if (input.recurrence === 'quarterly') return `${minute} ${hour} ${monthDay} 1,4,7,10 *`
  if (input.recurrence === 'yearly') {
    const annualMonth = Number(input.annualMonth)
    if (!Number.isInteger(annualMonth) || annualMonth < 1 || annualMonth > 12)
      throw new Error('Yearly recurrence requires a month between 1 and 12.')
    return `${minute} ${hour} ${monthDay} ${annualMonth} *`
  }
  return `${minute} ${hour} ${monthDay} * *`
}

export function isOperationalTaskOverdue(
  task: { status: string; dueAt: Date },
  now = new Date(),
): boolean {
  return !['completed', 'waived', 'cancelled'].includes(task.status) && task.dueAt < now
}

'use server'

import type { DiaryTemplateInput } from '@/lib/hospitality/diary-rules'
import { revalidatePath } from 'next/cache'
import { requireRequestContext } from '@/lib/auth'
import {
  completeDiaryTask,
  createDiaryTemplate,
  getOrCreateDiaryCorrectiveAction,
  setDiaryTemplateActive,
  updateDiaryTemplate,
} from '@/lib/hospitality/diary'
import { redirect } from 'next/navigation'

const value = (form: FormData, key: string) => String(form.get(key) ?? '')
const optional = (form: FormData, key: string) => value(form, key).trim() || undefined
const path = (propertyId: string) => `/hospitality/properties/${propertyId}/diary`

function input(form: FormData): DiaryTemplateInput {
  const recurrence = value(form, 'recurrence')
  if (
    recurrence !== 'daily' &&
    recurrence !== 'weekly' &&
    recurrence !== 'monthly' &&
    recurrence !== 'quarterly' &&
    recurrence !== 'yearly'
  )
    throw new Error('Invalid diary recurrence.')
  return {
    title: value(form, 'title'),
    instructions: optional(form, 'instructions'),
    recurrence,
    dueTime: value(form, 'dueTime'),
    weekday: optional(form, 'weekday'),
    monthDay: optional(form, 'monthDay'),
    annualMonth: optional(form, 'annualMonth'),
    timezone: value(form, 'timezone'),
    assigneeId: optional(form, 'assigneeId'),
  }
}

export async function createDiaryTemplateAction(form: FormData) {
  const ctx = await requireRequestContext()
  const propertyId = value(form, 'propertyId')
  await createDiaryTemplate(ctx, propertyId, input(form))
  revalidatePath(path(propertyId))
}

export async function updateDiaryTemplateAction(form: FormData) {
  const ctx = await requireRequestContext()
  const propertyId = value(form, 'propertyId')
  await updateDiaryTemplate(ctx, propertyId, value(form, 'scheduleId'), input(form))
  revalidatePath(path(propertyId))
}

export async function setDiaryTemplateActiveAction(form: FormData) {
  const ctx = await requireRequestContext()
  const propertyId = value(form, 'propertyId')
  await setDiaryTemplateActive(
    ctx,
    propertyId,
    value(form, 'scheduleId'),
    value(form, 'isActive') === 'true',
  )
  revalidatePath(path(propertyId))
}

export async function completeDiaryTaskAction(form: FormData) {
  const ctx = await requireRequestContext()
  const propertyId = value(form, 'propertyId')
  await completeDiaryTask(
    ctx,
    propertyId,
    value(form, 'occurrenceId'),
    value(form, 'completionNotes'),
  )
  revalidatePath(path(propertyId))
}

export async function createDiaryCorrectiveActionAction(form: FormData) {
  const ctx = await requireRequestContext()
  const propertyId = value(form, 'propertyId')
  const result = await getOrCreateDiaryCorrectiveAction(
    ctx,
    propertyId,
    value(form, 'occurrenceId'),
  )
  redirect(`/corrective-actions/${result.row.id}`)
}

