                    {translateHospitality('m_1c2654d15ea608')}{' '}
                  </Link>
                </Button>
                {manage && (
                  <Button asChild size="sm" variant="outline">
                    <Link
                      href={`/hospitality/properties/${propertyId}/diary/templates/${schedule.id}`}
